import { useEffect, useState } from 'react';
import { JxToggle, JxSlider, JxSwitch, JxDivider, JxSelect, JxBadge } from '@jinx-ui/react';

type ThemeValue = 'light' | 'dark' | 'system';

export interface AppearanceSettingsValue {
  theme: ThemeValue;
  scale: number;
  dense: boolean;
  font: string;
}

interface AppearanceSettingsProps {
  onChange?: (value: AppearanceSettingsValue) => void;
}

const THEME_LABELS: Record<ThemeValue, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceSettings({ onChange }: AppearanceSettingsProps) {
  const [theme, setTheme] = useState<ThemeValue>('system');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState('sans');

  useEffect(() => {
    onChange?.({ theme, scale, dense, font });
  }, [theme, scale, dense, font, onChange]);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 24,
        maxWidth: 440,
        padding: 24,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12 }}>
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            color: 'var(--jx-text)',
            fontSize: '1.25rem',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent">{THEME_LABELS[theme]}</JxBadge>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        <span style={{ color: 'var(--jx-text-2)', fontFamily: 'var(--jx-font-sans)', fontSize: '0.875rem' }}>
          Тема
        </span>
        <JxToggle
          items={[
            { value: 'light', label: 'Светлая' },
            { value: 'dark', label: 'Тёмная' },
            { value: 'system', label: 'Системная' },
          ]}
          value={theme}
          onValueChange={(value) => setTheme(value as ThemeValue)}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={scale}
        onValueChange={setScale}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={dense}
        onChange={(event) => setDense(event.target.checked)}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        options={[
          { value: 'sans', label: 'Inter Tight (по умолчанию)' },
          { value: 'serif', label: 'Fraunces' },
          { value: 'mono', label: 'JetBrains Mono' },
        ]}
        value={font}
        onValueChange={setFont}
      />
    </div>
  );
}

